scwin.deliverablesSubmitdone = function(start) {
	for (var i = start; i < dlMyTaskList.getRowCount(); i++) {
		if (dlMyTaskList.getCellData(i, 'lvlSeq') == 1) {
			gridView1.setCellReadOnly(i, 'check', true);
			gridView1.setCellReadOnly(i, 'result', true);
			gridView1.setCellReadOnly(i, 'score', true);
			gridView1.setCellReadOnly(i, 'remark', true);
		} else if (dlMyTaskList.getCellData(i, 'lvlSeq') == 2) {
			var verifyType = dlMyTaskList.getCellData(i, 'verifyType');
			var deliverType = dlMyTaskList.getCellData(i, 'deliverType');
			var taskStatus = dlMyTaskList.getCellData(i, 'taskStatus');
			var approvalStatus = dlMyTaskList.getCellData(i, 'approvalStatus');
			if (taskStatus == 'CP' || taskStatus == 'AP' || taskStatus == 'RJ') {
				if (deliverType != '08' && deliverType != '09') {
					dlMyTaskList.setCellData(i, 'deliverables', 'View');
				}
			}
			if (verifyType != '02') {
				gridView1.setCellReadOnly(i, 'score', true);
			}
			if (taskStatus != 'CP' || approvalStatus == 1) {
				gridView1.setCellReadOnly(i, 'check', true);
				gridView1.setCellReadOnly(i, 'result', true);
				gridView1.setCellReadOnly(i, 'score', true);
				gridView1.setCellReadOnly(i, 'remark', true);
			}
		}
	}
};
scwin.addData = function() {
	var gridCount = gridView1.getTotalRow();
	var addData = scwin.data.splice(0, 20);
	scwin.cnt++;
	dlMyTaskList.setJSON(addData, true);
};
scwin.gridView1_onscrollend = function() {
	scwin.addData();
};
scwin.fireDbClick = function(node) {
	if (document.createEventObject) {
		node.fireEvent('ondblclick');
	} else if (document.createEvent) {
		var evt = document.createEvent('MouseEvents');
		evt.initEvent('dblclick', true, false);
		node.dispatchEvent(evt);
	} else if (typeof node.ondblclick == 'function') {
		node.ondblclick();
	}
}
scwin.Dbclick = function(id) {
	var el = scwin.__getDom($p.id + id);
	scwin.fireDbClick(el);
}
scwin.checkColor = function(id, rgb) {
	var element = scwin.__getDom($p.id + id)
	var color = scwin.__getJq($(element).children()[0]).css("color");
	return color == rgb;
}
scwin.checkVal = function() {
	return (document.getElementById('gridView1_cell_3_14') || document.getElementById('mf_gridView1_cell_3_14')).classList.contains('w2grid_default_readonly');
}
scwin.onpageload = function() {
	scwin.doInit();
}
